const encoded="";
const extraEncoded="";
const css=".cb-feature-icon{display:inline-block!important;width:32px!important;height:32px!important;min-width:32px;flex:0 0 32px!important;vertical-align:middle;overflow:hidden;background-color:#fff!important;background-image:var(--cb-icon-sheet)!important;background-size:300% 200%!important;background-position:var(--cb-icon-x) var(--cb-icon-y)!important;background-repeat:no-repeat!important;border-radius:7px;font-size:0!important;line-height:0!important;margin-inline-end:9px}nav .cb-feature-link,.side-nav .cb-feature-link{display:flex!important;align-items:center!important;gap:0!important}.quick .cb-feature-icon{float:inline-start;width:40px!important;height:40px!important;min-width:40px;margin-block-end:5px}h1>.cb-feature-icon,h2>.cb-feature-icon{width:42px!important;height:42px!important;min-width:42px}nav .cb-feature-link:focus-visible,.side-nav .cb-feature-link:focus-visible{outline:2px solid #79c8df;outline-offset:3px}";
const client="(()=>{const map={'virtual-patient':[0,0],sessions:[0,1],forum:[0,2],learning:[0,3],backpack:[0,4],'crisis-backpack':[0,4],'site-guide':[0,5],overview:[1,0],dashboard:[1,0],assignments:[1,1],'learning-reports':[1,2],admin:[1,3],'growth-coins':[1,4],continuity:[1,5],cases:[0,0]};function key(el){if(el.dataset.view)return el.dataset.view;try{const url=new URL(el.getAttribute('href'),location.href);return url.pathname==='/dashboard'?'dashboard':url.searchParams.get('view')}catch{return null}}function apply(el,k,heading=false){const item=map[k];if(!item)return;const [sheet,i]=item,identity=sheet+'-'+i;if(el.dataset.cbFeatureIcon===identity)return;let icon=Array.from(el.children).find(n=>n.classList.contains('cb-feature-icon'));if(!icon&&!heading)icon=Array.from(el.children).find(n=>n.tagName==='SPAN'&&(el.matches('button[data-view]')||n.getAttribute('aria-hidden')==='true'));if(!icon){icon=document.createElement('span');el.prepend(icon)}icon.className='cb-feature-icon';icon.setAttribute('aria-hidden','true');icon.textContent='';icon.style.setProperty('--cb-icon-x',(i%3)*50+'%');icon.style.setProperty('--cb-icon-y',i<3?'0%':'100%');icon.style.setProperty('--cb-icon-sheet',\"url('/brand/feature-icons-\"+(sheet?'extra-v2':'base-v2')+\".webp')\");el.dataset.cbFeatureIcon=identity;el.classList.add('cb-feature-link')}function scan(){document.querySelectorAll('nav button[data-view],.side-nav a,.quick a,[data-cb-icon]').forEach(el=>apply(el,el.dataset.cbIcon||key(el)));for(const k of Object.keys(map)){const s=document.getElementById(k);if(s){const h=s.querySelector('h1,h2');if(h)apply(h,k,true)}}}let queued=false;scan();new MutationObserver(()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;scan()})}).observe(document.body,{childList:true,subtree:true});})();";
export function featureIconResponse(request){const path=new URL(request.url).pathname;const resources=['/brand/feature-icons-base-v2.webp','/brand/feature-icons-extra-v2.webp','/brand/feature-icons-v2.css','/brand/feature-icons-v2.js','/brand/feature-icons-v3.css','/brand/feature-icons-v3.js','/brand/feature-icons-v1.webp'];if(!resources.includes(path))return null;if(!['GET','HEAD'].includes(request.method))return new Response(null,{status:405,headers:{Allow:'GET, HEAD'}});let body,type;if(path.endsWith('.webp')){body=Uint8Array.from(atob(path.includes('extra')?extraEncoded:encoded),c=>c.charCodeAt(0));type='image/webp'}else if(path.endsWith('.css')){body=css;type='text/css; charset=utf-8'}else{body=client;type='text/javascript; charset=utf-8'}return new Response(request.method==='HEAD'?null:body,{headers:{'Content-Type':type,'Cache-Control':'public, max-age=86400','X-Content-Type-Options':'nosniff'}})}
export function decorateFeatureIcons(html){return html.replace(/<link\b[^>]*href=["']\/brand\/feature-icons-v\d+\.css["'][^>]*>/g,'').replace(/<script\b[^>]*src=["']\/brand\/feature-icons-v\d+\.js["'][^>]*>\s*<\/script>/g,'').replace('</head>','<link id="cb-feature-icons-css" rel="stylesheet" href="/brand/feature-icons-v3.css"></head>').replace('</body>','<script id="cb-feature-icons-js" src="/brand/feature-icons-v3.js" defer></script></body>')}
